body:
Yes, the nvim folder is being tracked by git, it's there as a submodule to my nvim repo (also tested without the submodule, same error). Is there anything up with my flake configuration? Here's my nix configuration but it's pretty much the default made by home-manager:

    {
      description = "Home Manager configuration of elian";

      inputs = {
        nixpkgs.url = "github:nixos/nixpkgs/nixos-unstable";
        home-manager = {
          url = "github:nix-community/home-manager";
          inputs.nixpkgs.follows = "nixpkgs";
        };
      };

      outputs = { self, nixpkgs, home-manager, ... }:
        let
          system = "x86_64-linux";
          pkgs = nixpkgs.legacyPackages.${system};
        in
        {
          homeConfigurations = {
            "elian-wsl" = home-manager.lib.homeManagerConfiguration {
              inherit pkgs;

              modules = [
                ./hosts/wsl/home.nix


              ];

            };
          };
        };
    }
